    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a sosa:Observation ;
                    sosa:hasFeatureOfInterest [ ] ;
                    sosa:hasSimpleResult "" ;
                    sosa:observedProperty [ ] ;
                    sosa:phenomenonTime "2025-01-01T00:00:00+00:00"^^xsd:dateTime,
                        "2025-01-02T00:00:00+00:00"^^xsd:dateTime ] ;
            sh:resultMessage "At most one http://www.w3.org/ns/sosa/phenomenonTime is allowed. A member of a collection with several http://www.w3.org/ns/sosa/phenomenonTime values must give its own: 2 values" ;
            sh:resultPath sosa:phenomenonTime ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "At most one {?path} is allowed. A member of a collection with several {?path} values must give its own: {?value}" ;
                    sh:select """
            PREFIX sosa: <http://www.w3.org/ns/sosa/>
            PREFIX geojson: <https://purl.org/geojson/vocab#>
            SELECT $this ?path (CONCAT(STR(COUNT(DISTINCT ?time)), ' values') AS ?value) WHERE {
                {
                    $this ?path ?time .
                    FILTER(?path IN (sosa:resultTime, sosa:phenomenonTime))
                } UNION {
                    # Binding ?path first (rather than filtering it afterwards) means the costly
                    # "nearer" test below runs only for time values, not for every property of the
                    # collection (e.g. all its features). VALUES is not allowed in SHACL-SPARQL.
                    { BIND(sosa:resultTime AS ?path) } UNION { BIND(sosa:phenomenonTime AS ?path) }
                    ?holder (sosa:hasMember|geojson:features|^sosa:memberOf)+ $this ;
                        ?path ?time .
                    FILTER NOT EXISTS { $this ?path ?own }
                    FILTER NOT EXISTS {
                        ?holder (sosa:hasMember|geojson:features|^sosa:memberOf)+ ?nearer .
                        ?nearer (sosa:hasMember|geojson:features|^sosa:memberOf)+ $this ;
                            ?path ?nearerTime .
                    }
                }
            }
            GROUP BY $this ?path
            HAVING (COUNT(DISTINCT ?time) > 1)
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/sosa/#testRequiredTime> ;
            sh:value "2 values" ] .

